 M('집', '한 변이 100인 정사각형 위에 지붕(정삼각형)을 얹어요.', '도형 두 개를 이어 그리려면 거북이가 어디에서 어느 쪽을 보는지 따라가요.', R(4, ('fd', 100), ('rt', 90)) + [('fd', 100), ('rt', 30)] + R(3, ('fd', 100), ('rt', 120)), (150, 320, 0), hint='정사각형을 그리고 왼쪽 위로 올라가 30° 돌린 뒤 정삼각형'),
